//! 🔤️ IDML paragraph/character styles and UTF8-native story ranges.
use super::*;
use semio_s_artifact_layout_layout_model::{ParagraphStyle,CharacterStyle,TextStyleRun};
fn property(node:&XmlNode,key:&str)->Option<String>{let props=children(node).iter().find(|node|local(node)=="Properties")?;let value=children(props).iter().find(|node|local(node)==key)?;let mut out=String::new();text(value,&mut out);Some(out)}
fn property_node(key:&str,value:String,kind:&str)->XmlNode{element(key,vec![("type",kind.into())],vec![XmlNode::Text{text:value}])}
fn number(node:&XmlNode,key:&str)->Result<Option<f64>,String>{let Some(value)=attr(node,key).map(str::to_string).or_else(||property(node,key))else{return Ok(None)};if value=="Auto"{return Ok(None)}let number=value.parse::<f64>().map_err(|_|"layout.idml.style-number")?;if !number.is_finite(){return Err("layout.idml.style-number".into());}Ok(Some(number))}
fn font_style(weight:u32,italic:bool)->String{let face=match weight{0..=150=>"Thin",151..=250=>"ExtraLight",251..=350=>"Light",351..=450=>"Regular",451..=550=>"Medium",551..=650=>"SemiBold",651..=750=>"Bold",751..=850=>"ExtraBold",_=>"Black"};if italic{format!("{face} Italic")}else{face.into()}}
fn weight(face:&str)->u32{if face.contains("ExtraBold"){800}else if face.contains("SemiBold"){600}else if face.contains("Bold"){700}else if face.contains("Black"){900}else if face.contains("ExtraLight"){200}else if face.contains("Light"){300}else if face.contains("Thin"){100}else if face.contains("Medium"){500}else{400}}
fn alignment(value:&str)->Result<&'static str,String>{match value{"left"|"LeftAlign"=>Ok("LeftAlign"),"center"|"CenterAlign"=>Ok("CenterAlign"),"right"|"RightAlign"=>Ok("RightAlign"),"justify"|"LeftJustified"|"FullyJustified"=>Ok("LeftJustified"),_=>Err("layout.idml.justification".into())}}
pub(crate) fn paragraph_node(style:&ParagraphStyle)->Result<XmlNode,String>{Ok(element("ParagraphStyle",vec![("Self",style.id.clone()),("Name",style.name.clone()),("PointSize",style.font_size.to_string()),("FontStyle",font_style(style.font_weight,false)),("Tracking",style.tracking.to_string()),("Justification",alignment(&style.alignment)?.into())],vec![element("Properties",Vec::new(),vec![property_node("AppliedFont",style.font_family.clone(),"string"),property_node("Leading",style.leading.to_string(),"unit")])]))}
pub(crate) fn character_node(style:&CharacterStyle)->Result<XmlNode,String>{let mut attrs=vec![("Self",style.id.clone())];if let Some(name)=&style.name{attrs.push(("Name",name.clone()));}if let Some(size)=style.font_size{attrs.push(("PointSize",size.to_string()));}if let Some(tracking)=style.tracking{attrs.push(("Tracking",tracking.to_string()));}if style.font_weight.is_some()||style.italic.is_some(){attrs.push(("FontStyle",font_style(style.font_weight.unwrap_or(400),style.italic.unwrap_or(false))));}if style.color.is_some(){attrs.push(("FillColor",format!("Color/style-{}",style.id)));}let mut properties=Vec::new();if let Some(font)=&style.font_family{properties.push(property_node("AppliedFont",font.clone(),"string"));}Ok(element("CharacterStyle",attrs,if properties.is_empty(){Vec::new()}else{vec![element("Properties",Vec::new(),properties)]}))}
pub(crate) fn character_color(style:&CharacterStyle)->Result<Option<XmlNode>,String>{let Some(color)=style.color else{return Ok(None)};if color.iter().any(|channel|!channel.is_finite()||*channel<0.0||*channel>1.0)||color[3]!=1.0{return Err("layout.idml.text-color-alpha".into());}Ok(Some(element("Color",vec![("Self",format!("Color/style-{}",style.id)),("Name",format!("style-{}",style.id)),("Model","Process".into()),("Space","RGB".into()),("ColorValue",format!("{} {} {}",color[0]*255.0,color[1]*255.0,color[2]*255.0))],Vec::new())))}
fn paragraph_style(source:&XmlNode,base:Option<&ParagraphStyle>,id:String)->Result<ParagraphStyle,String>{let size=number(source,"PointSize")?.or(base.map(|base|base.font_size)).unwrap_or(12.0);let justify=alignment(attr(source,"Justification").unwrap_or_else(||base.map_or("left",|base|base.alignment.as_str())))?;Ok(ParagraphStyle{id,name:attr(source,"Name").unwrap_or("Paragraph").into(),font_family:property(source,"AppliedFont").or_else(||attr(source,"AppliedFont").map(str::to_string)).or_else(||base.map(|base|base.font_family.clone())).unwrap_or_else(||"sans-serif".into()),font_size:size,font_weight:attr(source,"FontStyle").map(weight).or(base.map(|base|base.font_weight)).unwrap_or(400),leading:number(source,"Leading")?.or(base.map(|base|base.leading)).unwrap_or(size*1.2),tracking:number(source,"Tracking")?.or(base.map(|base|base.tracking)).unwrap_or(0.0),alignment:match justify{"CenterAlign"=>"center","RightAlign"=>"right","LeftJustified"=>"justify",_=>"left"}.into()})}
fn character_style(source:&XmlNode,base:Option<&CharacterStyle>,colors:&BTreeMap<String,[f32;4]>,id:String)->Result<CharacterStyle,String>{let face=attr(source,"FontStyle");Ok(CharacterStyle{id,name:attr(source,"Name").map(str::to_string),font_family:property(source,"AppliedFont").or_else(||attr(source,"AppliedFont").map(str::to_string)).or_else(||base.and_then(|base|base.font_family.clone())),font_size:number(source,"PointSize")?.or(base.and_then(|base|base.font_size)),font_weight:face.map(weight).or(base.and_then(|base|base.font_weight)),italic:face.map(|face|face.contains("Italic")||face.contains("Oblique")).or(base.and_then(|base|base.italic)),color:if attr(source,"FillColor").is_some(){paint(source,"FillColor",colors)?}else{base.and_then(|base|base.color)},tracking:number(source,"Tracking")?.or(base.and_then(|base|base.tracking))})}
fn based_on(node:&XmlNode)->Option<String>{property(node,"BasedOn").or_else(||attr(node,"BasedOn").map(str::to_string)).filter(|id|id!="n"&&id!="[No paragraph style]"&&id!="[No character style]")}
fn resolve_paragraph(id:&str,sources:&BTreeMap<String,&XmlNode>,resolved:&mut BTreeMap<String,ParagraphStyle>,visiting:&mut HashSet<String>)->Result<ParagraphStyle,String>{if let Some(style)=resolved.get(id){return Ok(style.clone());}if !visiting.insert(id.into()){return Err("layout.idml.style-cycle".into());}let node=sources.get(id).ok_or("layout.idml.missing-base-style")?;let base=if let Some(base)=based_on(node){Some(resolve_paragraph(&base,sources,resolved,visiting)?)}else{None};let style=paragraph_style(node,base.as_ref(),id.into())?;visiting.remove(id);resolved.insert(id.into(),style.clone());Ok(style)}
fn resolve_character(id:&str,sources:&BTreeMap<String,&XmlNode>,resolved:&mut BTreeMap<String,CharacterStyle>,visiting:&mut HashSet<String>,colors:&BTreeMap<String,[f32;4]>)->Result<CharacterStyle,String>{if let Some(style)=resolved.get(id){return Ok(style.clone());}if !visiting.insert(id.into()){return Err("layout.idml.style-cycle".into());}let node=sources.get(id).ok_or("layout.idml.missing-base-style")?;let base=if let Some(base)=based_on(node){Some(resolve_character(&base,sources,resolved,visiting,colors)?)}else{None};let style=character_style(node,base.as_ref(),colors,id.into())?;visiting.remove(id);resolved.insert(id.into(),style.clone());Ok(style)}
pub(crate) fn import_styles(doc:&mut LayoutSnapshot,entries:&BTreeMap<String,Vec<u8>>,root:&XmlNode,colors:&BTreeMap<String,[f32;4]>)->Result<(),String>{
    for reference in nodes(root,"Styles")?{let Some(src)=attr(reference,"src")else{continue};let part=read_xml(entries,src)?;let paragraphs=nodes(&part,"ParagraphStyle")?;let characters=nodes(&part,"CharacterStyle")?;let p_sources=paragraphs.iter().map(|node|Ok((identity(node)?,*node))).collect::<Result<BTreeMap<_,_>,String>>()?;let c_sources=characters.iter().map(|node|Ok((identity(node)?,*node))).collect::<Result<BTreeMap<_,_>,String>>()?;let mut p_resolved=BTreeMap::new();let mut c_resolved=BTreeMap::new();let mut visiting=HashSet::new();
        for source in paragraphs{let id=identity(source)?;if id=="ParagraphStyle/$ID/NormalParagraphStyle"&&attr(source,"PointSize").is_none()&&property(source,"AppliedFont").is_none(){continue;}doc.paragraph_styles.push(resolve_paragraph(&id,&p_sources,&mut p_resolved,&mut visiting)?);}
        for source in characters{let id=identity(source)?;if id=="CharacterStyle/$ID/[No character style]"{continue;}doc.character_styles.push(resolve_character(&id,&c_sources,&mut c_resolved,&mut visiting,colors)?);}
    }Ok(())
}
fn append(story:&mut TextStory,value:&str,paragraph:Option<&str>,character:Option<&str>){let start=story.content.len()as u64;story.content.push_str(value);let end=story.content.len()as u64;if start==end||paragraph.is_none()&&character.is_none(){return;}if let Some(previous)=story.style_runs.last_mut(){if previous.end==start&&previous.paragraph_style_id.as_deref()==paragraph&&previous.character_style_id.as_deref()==character{previous.end=end;return;}}story.style_runs.push(TextStyleRun{start,end,paragraph_style_id:paragraph.map(str::to_string),character_style_id:character.map(str::to_string)});}
fn inline_paragraph(node:&XmlNode,doc:&mut LayoutSnapshot,current:Option<String>)->Result<Option<String>,String>{let direct=attr(node,"AppliedParagraphStyle").map(str::to_string).or(current);let reference=direct.filter(|id|doc.paragraph_styles.iter().any(|style|&style.id==id));if !["PointSize","FontStyle","Tracking","Justification","AppliedFont","Leading"].iter().any(|key|attr(node,key).is_some())&&property(node,"AppliedFont").is_none()&&property(node,"Leading").is_none(){return Ok(reference);}let base=reference.as_ref().and_then(|id|doc.paragraph_styles.iter().find(|style|&style.id==id));let mut sequence=doc.paragraph_styles.len()+1;while doc.paragraph_styles.iter().any(|style|style.id==format!("inline-paragraph-{sequence}")){sequence+=1;}let id=format!("inline-paragraph-{sequence}");let style=paragraph_style(node,base,id.clone())?;doc.paragraph_styles.push(style);Ok(Some(id))}
fn inline_character(node:&XmlNode,doc:&mut LayoutSnapshot,current:Option<String>,colors:&BTreeMap<String,[f32;4]>)->Result<Option<String>,String>{let direct=attr(node,"AppliedCharacterStyle").map(str::to_string).or(current);let reference=direct.filter(|id|doc.character_styles.iter().any(|style|&style.id==id));if !["PointSize","FontStyle","Tracking","FillColor","AppliedFont"].iter().any(|key|attr(node,key).is_some())&&property(node,"AppliedFont").is_none(){return Ok(reference);}let base=reference.as_ref().and_then(|id|doc.character_styles.iter().find(|style|&style.id==id));let mut sequence=doc.character_styles.len()+1;while doc.character_styles.iter().any(|style|style.id==format!("inline-character-{sequence}")){sequence+=1;}let id=format!("inline-character-{sequence}");let style=character_style(node,base,colors,id.clone())?;doc.character_styles.push(style);Ok(Some(id))}
fn walk_story(node:&XmlNode,story:&mut TextStory,paragraph:Option<String>,character:Option<String>,doc:&mut LayoutSnapshot,colors:&BTreeMap<String,[f32;4]>)->Result<(),String>{let paragraph=if local(node)=="ParagraphStyleRange"{inline_paragraph(node,doc,paragraph)?}else{paragraph};let character=if local(node)=="CharacterStyleRange"{inline_character(node,doc,character,colors)?}else{character};match local(node){"Content"=>{let mut value=String::new();text(node,&mut value);append(story,&value,paragraph.as_deref(),character.as_deref());},"Br"=>append(story,"\n",paragraph.as_deref(),character.as_deref()),_=>for child in children(node){walk_story(child,story,paragraph.clone(),character.clone(),doc,colors)?;}}Ok(())}
pub(crate) fn import_story(node:&XmlNode,doc:&mut LayoutSnapshot,colors:&BTreeMap<String,[f32;4]>)->Result<TextStory,String>{let mut story=TextStory{id:identity(node)?,content:String::new(),style_runs:Vec::new()};walk_story(node,&mut story,None,None,doc,colors)?;Ok(story)}
#[derive(Debug)]
pub(crate) struct StoryFragmentPlan{start:usize,end:usize,index:usize,owner:Option<usize>}
impl StoryFragmentPlan{
    pub(crate) fn new(story:&TextStory,start:usize)->Result<Self,String>{if start>=story.content.len()||!story.content.is_char_boundary(start){return Err("layout.idml.story-cursor".into());}let mut end=(start+512).min(story.content.len());while !story.content.is_char_boundary(end){end-=1;}Ok(Self{start,end,index:0,owner:None})}
    pub(crate) fn advance(&mut self,story:&TextStory)->Result<Option<(usize,XmlNode)>,String>{
        if let Some(run)=story.style_runs.get(self.index){let a=usize::try_from(run.start).map_err(|_|"layout.idml.style-range")?;let b=usize::try_from(run.end).map_err(|_|"layout.idml.style-range")?;if a>b||b>story.content.len()||!story.content.is_char_boundary(a)||!story.content.is_char_boundary(b){return Err("layout.idml.style-range".into());}if a>self.start{self.end=self.end.min(a);}if b>self.start{self.end=self.end.min(b);}if a<=self.start&&b>self.start{self.owner=Some(self.index);}self.index+=1;return Ok(None);}
        let run=self.owner.and_then(|index|story.style_runs.get(index));let paragraph=run.and_then(|run|run.paragraph_style_id.as_deref());let character=run.and_then(|run|run.character_style_id.as_deref());
        let content=if story.content.as_bytes()[self.start]==b'\n'{self.end=self.start+1;element("Br",Vec::new(),Vec::new())}else{if let Some(next)=story.content[self.start..self.end].find('\n'){self.end=self.start+next;}while !story.content.is_char_boundary(self.end){self.end-=1;}element("Content",Vec::new(),vec![XmlNode::Text{text:story.content[self.start..self.end].into()}])};
        Ok(Some((self.end,element("ParagraphStyleRange",vec![("AppliedParagraphStyle",paragraph.unwrap_or("ParagraphStyle/$ID/NormalParagraphStyle").into())],vec![element("CharacterStyleRange",vec![("AppliedCharacterStyle",character.unwrap_or("CharacterStyle/$ID/[No character style]").into())],vec![content])]))))
    }
}
pub(crate) fn story_fragment(story:&TextStory,start:usize)->Result<(usize,XmlNode),String>{let mut plan=StoryFragmentPlan::new(story,start)?;loop{if let Some(fragment)=plan.advance(story)?{return Ok(fragment);}}}

pub(crate) fn frame_preferences(frame:&Frame)->Result<Vec<XmlNode>,String>{let Frame::Text{columns,inset,wrap_mode,..}=frame else{return Ok(Vec::new())};if !(1..=40).contains(columns){return Err("layout.idml.text-column-limit".into());}let mode=match wrap_mode.as_str(){"none"=>"None","bounds"|"bounding-box"=>"BoundingBoxTextWrap","shape"=>"Contour",_=>return Err("layout.idml.text-wrap-mode".into())};let spacing=[inset.y,inset.x,inset.height,inset.width].into_iter().map(|value|property_node("ListItem",value.to_string(),"unit")).collect();Ok(vec![element("TextFramePreference",vec![("TextColumnCount",columns.to_string()),("UseFixedColumnWidth","false".into())],vec![element("Properties",Vec::new(),vec![element("InsetSpacing",vec![("type","list".into())],spacing)])]),element("TextWrapPreference",vec![("TextWrapMode",mode.into())],Vec::new())])}
pub(crate) fn read_frame_preferences(source:&XmlNode)->Result<(u32,LayoutRect,String),String>{let preference=children(source).iter().find(|node|local(node)=="TextFramePreference");let columns=preference.and_then(|node|attr(node,"TextColumnCount")).unwrap_or("1").parse::<u32>().map_err(|_|"layout.idml.text-column-limit")?;if !(1..=40).contains(&columns){return Err("layout.idml.text-column-limit".into());}let mut spacing=vec![0.0;4];if let Some(preference)=preference{if let Some(node)=nodes(preference,"InsetSpacing")?.first(){let values=nodes(node,"ListItem")?;if values.len()!=4{return Err("layout.idml.text-inset".into());}for(index,node)in values.iter().enumerate(){let mut value=String::new();text(node,&mut value);spacing[index]=value.parse::<f64>().map_err(|_|"layout.idml.text-inset")?;if !spacing[index].is_finite(){return Err("layout.idml.text-inset".into());}}}}let mode=children(source).iter().find(|node|local(node)=="TextWrapPreference").and_then(|node|attr(node,"TextWrapMode")).unwrap_or("None");let wrap_mode=match mode{"None"=>"none","BoundingBoxTextWrap"=>"bounds","Contour"=>"shape",_=>return Err("layout.idml.text-wrap-mode".into())};Ok((columns,LayoutRect{x:spacing[1],y:spacing[0],width:spacing[3],height:spacing[2]},wrap_mode.into()))}
